namespace RogControlDiscovery {
 public sealed class DiscoveryNode {
  public string InstanceId,ParentId,ContainerId,FriendlyName,BusName,Description;
  public string[] HardwareIds=new string[0];public bool Present,InLocalMachineContainer;
 }
 public sealed class DiscoveryDevice {
  public string deviceId {get;set;} public string name {get;set;} public string nameSource {get;set;}
  public string vid {get;set;} public string pid {get;set;} public string transport {get;set;}
  public bool present {get;set;} public bool vendorConfirmed {get;set;} public bool controlSupported {get;set;}
  public bool physicalIdentityConfirmed {get;set;} public string identityScope {get;set;}
  public int functionCount {get;set;} public string[] observedProductIds {get;set;}
 }
 public static class DiscoveryRules {
  static readonly Regex UsbIdentity=new Regex(@"^(?:USB|HID)\\VID_([0-9A-F]{4})&PID_([0-9A-F]{4})(?=[&\\]|$)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant);
  public static bool ParseIdentity(string text,out string vid,out string pid){vid=pid="";if(text==null||text.Length>4096)return false;var match=UsbIdentity.Match(text);if(!match.Success)return false;vid=match.Groups[1].Value.ToUpperInvariant();pid=match.Groups[2].Value.ToUpperInvariant();return true;}
  static bool Asus(DiscoveryNode node){string vid,pid;bool parsed=ParseIdentity(node.InstanceId,out vid,out pid);if(parsed&&vid!="0B05")return false;bool found=parsed;foreach(string hw in node.HardwareIds??new string[0]){string vendor,product;if(!ParseIdentity(hw,out vendor,out product))continue;if(vendor!="0B05"||found&&(vendor!=vid||product!=pid))return false;if(!found){vid=vendor;pid=product;found=true;}}return found;}
  static bool Eligible(DiscoveryNode node){return node!=null&&node.Present&&!String.IsNullOrEmpty(node.InstanceId)&&(node.InstanceId.StartsWith("USB\\",StringComparison.OrdinalIgnoreCase)||node.InstanceId.StartsWith("HID\\",StringComparison.OrdinalIgnoreCase))&&Asus(node);}
  public static string Clean(string text){return String.IsNullOrEmpty(text)?"":new string(text.Where(c=>!Char.IsControl(c)).Take(240).ToArray()).Trim();}
  static DiscoveryNode UsbRoot(DiscoveryNode node,IDictionary<string,DiscoveryNode> nodes){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<32&&node!=null&&node.Present&&seen.Add(node.InstanceId);i++){string vid,pid;string part=node.InstanceId.Split('\\')[0]+"\\"+(node.InstanceId.Split('\\').Length>1?node.InstanceId.Split('\\')[1]:"");if(node.InstanceId.StartsWith("USB\\",StringComparison.OrdinalIgnoreCase)&&ParseIdentity(node.InstanceId,out vid,out pid)&&part.IndexOf("&MI_",StringComparison.OrdinalIgnoreCase)<0)return node;DiscoveryNode parent;if(String.IsNullOrEmpty(node.ParentId)||!nodes.TryGetValue(node.ParentId,out parent))break;node=parent;}return null;}
  static string Container(string value){Guid id;return Guid.TryParse(value,out id)&&id!=Guid.Empty&&id!=new Guid("00000000-0000-0000-ffff-ffffffffffff")?id.ToString("D"):"";}
  static string NodeContainer(DiscoveryNode node){return node==null||node.InLocalMachineContainer?"":Container(node.ContainerId);}
  static string Hash(string value){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(value.ToUpperInvariant()))).Replace("-","").ToLowerInvariant();}
  public static List<DiscoveryDevice> Build(IEnumerable<DiscoveryNode> source){var nodes=(source??Enumerable.Empty<DiscoveryNode>()).Where(n=>n!=null&&n.Present&&!String.IsNullOrEmpty(n.InstanceId)).GroupBy(n=>n.InstanceId,StringComparer.OrdinalIgnoreCase).ToDictionary(g=>g.Key,g=>g.First(),StringComparer.OrdinalIgnoreCase);var groups=new Dictionary<string,List<DiscoveryNode>>(StringComparer.OrdinalIgnoreCase);var roots=new Dictionary<string,DiscoveryNode>(StringComparer.OrdinalIgnoreCase);
   var containerRoots=nodes.Values.Where(Eligible).Where(n=>n.InstanceId.StartsWith("USB\\",StringComparison.OrdinalIgnoreCase)&&Object.ReferenceEquals(UsbRoot(n,nodes),n)&&NodeContainer(n).Length>0).GroupBy(NodeContainer,StringComparer.OrdinalIgnoreCase).ToDictionary(g=>g.Key,g=>g.ToList(),StringComparer.OrdinalIgnoreCase);
   foreach(var node in nodes.Values.Where(Eligible)){var root=UsbRoot(node,nodes);if(root!=null&&!Eligible(root))continue;string container=NodeContainer(root??node);List<DiscoveryNode> knownRoots;bool ambiguous=false;if(root==null&&container.Length>0&&containerRoots.TryGetValue(container,out knownRoots)){if(knownRoots.Count==1)root=knownRoots[0];else ambiguous=true;}string key=root!=null?"usb:"+root.InstanceId:container.Length>0?(ambiguous?"ambiguousFunctions:":"container:")+container:"function:"+node.InstanceId;List<DiscoveryNode> members;if(!groups.TryGetValue(key,out members)){members=new List<DiscoveryNode>();groups[key]=members;roots[key]=root;}members.Add(node);}
   var result=new List<DiscoveryDevice>();foreach(var group in groups){var root=roots[group.Key];var members=group.Value.OrderBy(n=>n.InstanceId,StringComparer.OrdinalIgnoreCase).ToList();var representative=root??members.First();var products=new SortedSet<string>(StringComparer.Ordinal);foreach(var member in members){string v,p;if(ParseIdentity(member.InstanceId,out v,out p)&&v=="0B05")products.Add(p);else foreach(string hw in member.HardwareIds??new string[0])if(ParseIdentity(hw,out v,out p)&&v=="0B05")products.Add(p);}
    string vid="0B05",pid="";if(root!=null)ParseIdentity(root.InstanceId,out vid,out pid);else if(products.Count==1)pid=products.First();
    string name=Clean(representative.BusName),nameSource="busReportedDeviceDesc";if(name.Length==0){name=Clean(representative.FriendlyName);nameSource="friendlyName";}if(name.Length==0){name=Clean(representative.Description);nameSource="deviceDescription";}if(name.Length==0)nameSource="unavailable";
    result.Add(new DiscoveryDevice{deviceId=Hash(group.Key),name=name,nameSource=nameSource,vid=vid,pid=pid,transport=root!=null?"USB":"unknown",present=true,vendorConfirmed=true,controlSupported=false,physicalIdentityConfirmed=root!=null||group.Key.StartsWith("container:",StringComparison.Ordinal),identityScope=root!=null?"usbParent":group.Key.StartsWith("container:",StringComparison.Ordinal)?"container":"function",functionCount=members.Count,observedProductIds=products.ToArray()});
   }return result.OrderBy(d=>d.name,StringComparer.OrdinalIgnoreCase).ThenBy(d=>d.deviceId,StringComparer.Ordinal).ToList();
  }
 }
 internal static class WindowsDiscovery {
  const uint Present=2,AllClasses=4;const uint GuidType=13,StringType=18;static readonly IntPtr Invalid=new IntPtr(-1);
  [StructLayout(LayoutKind.Sequential)]struct DeviceInfo{public uint cbSize;public Guid ClassGuid;public uint DevInst;public IntPtr Reserved;}
  [StructLayout(LayoutKind.Sequential)]struct PropertyKey{public Guid fmtid;public uint pid;public PropertyKey(string id,uint property){fmtid=new Guid(id);pid=property;}}
  [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr SetupDiGetClassDevsW(IntPtr guid,string enumerator,IntPtr parent,uint flags);
  [DllImport("setupapi.dll",SetLastError=true)]static extern bool SetupDiEnumDeviceInfo(IntPtr set,uint index,ref DeviceInfo info);
  [DllImport("setupapi.dll",SetLastError=true)]static extern bool SetupDiDestroyDeviceInfoList(IntPtr set);
  [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool SetupDiGetDeviceInstanceIdW(IntPtr set,ref DeviceInfo info,StringBuilder text,uint characters,out uint required);
  [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool SetupDiGetDeviceRegistryPropertyW(IntPtr set,ref DeviceInfo info,uint property,out uint type,byte[] buffer,uint bytes,out uint required);
  [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool SetupDiGetDevicePropertyW(IntPtr set,ref DeviceInfo info,ref PropertyKey key,out uint type,byte[] buffer,uint bytes,out uint required,uint flags);
  [DllImport("cfgmgr32.dll")]static extern uint CM_Get_Parent(out uint parent,uint node,uint flags);
  [DllImport("cfgmgr32.dll",CharSet=CharSet.Unicode)]static extern uint CM_Get_Device_IDW(uint node,StringBuilder text,uint characters,uint flags);
  [DllImport("cfgmgr32.dll")]static extern uint CM_Get_DevNode_Status(out uint status,out uint problem,uint node,uint flags);
  static string Registry(IntPtr set,ref DeviceInfo info,uint property){uint type,needed;var bytes=new byte[65536];if(!SetupDiGetDeviceRegistryPropertyW(set,ref info,property,out type,bytes,(uint)bytes.Length,out needed)||needed>bytes.Length||(type!=1&&type!=2&&type!=7))return "";return Encoding.Unicode.GetString(bytes,0,(int)needed).TrimEnd('\0');}
  static byte[] Property(IntPtr set,ref DeviceInfo info,PropertyKey key,uint expected){uint type,needed;var bytes=new byte[65536];if(!SetupDiGetDevicePropertyW(set,ref info,ref key,out type,bytes,(uint)bytes.Length,out needed,0)||type!=expected||needed>bytes.Length)return null;var value=new byte[needed];Array.Copy(bytes,value,needed);return value;}
  static string ContainerId(IntPtr set,ref DeviceInfo info){var value=Property(set,ref info,new PropertyKey("8c7ed206-3f8a-4827-b3ab-ae9e1faefc6c",2),GuidType);return value!=null&&value.Length==16?new Guid(value).ToString("D"):"";}
  static string BusName(IntPtr set,ref DeviceInfo info){var value=Property(set,ref info,new PropertyKey("540b947e-8b40-45bc-a8a2-6a0b894cbda2",4),StringType);return value==null?"":Encoding.Unicode.GetString(value).TrimEnd('\0');}
  static bool LocalMachineContainer(IntPtr set,ref DeviceInfo info){var value=Property(set,ref info,new PropertyKey("8c7ed206-3f8a-4827-b3ab-ae9e1faefc6c",4),17);return value!=null&&value.Length==1&&value[0]!=0;}
  public static List<DiscoveryNode> Scan(){var clock=Stopwatch.StartNew();var set=SetupDiGetClassDevsW(IntPtr.Zero,null,IntPtr.Zero,Present|AllClasses);if(set==Invalid)throw new Win32Exception(Marshal.GetLastWin32Error());var result=new List<DiscoveryNode>();try{for(uint index=0;index<4096;index++){if(clock.ElapsedMilliseconds>15000)throw new TimeoutException("Windows device enumeration exceeded its read-only time budget.");var info=new DeviceInfo{cbSize=(uint)Marshal.SizeOf(typeof(DeviceInfo))};if(!SetupDiEnumDeviceInfo(set,index,ref info)){int error=Marshal.GetLastWin32Error();if(error==259)return result;throw new Win32Exception(error);}uint required;var instance=new StringBuilder(4096);if(!SetupDiGetDeviceInstanceIdW(set,ref info,instance,(uint)instance.Capacity,out required))continue;uint status,problem;if(CM_Get_DevNode_Status(out status,out problem,info.DevInst,0)!=0)continue;string id=instance.ToString();var node=new DiscoveryNode{InstanceId=id,Present=true};uint parent;if(CM_Get_Parent(out parent,info.DevInst,0)==0){var parentId=new StringBuilder(4096);if(CM_Get_Device_IDW(parent,parentId,(uint)parentId.Capacity,0)==0)node.ParentId=parentId.ToString();}
    if(id.StartsWith("USB\\",StringComparison.OrdinalIgnoreCase)||id.StartsWith("HID\\",StringComparison.OrdinalIgnoreCase)){node.HardwareIds=Registry(set,ref info,1).Split(new[]{'\0'},StringSplitOptions.RemoveEmptyEntries);node.FriendlyName=Registry(set,ref info,12);node.Description=Registry(set,ref info,0);node.BusName=BusName(set,ref info);node.ContainerId=ContainerId(set,ref info);node.InLocalMachineContainer=LocalMachineContainer(set,ref info);}result.Add(node);
   }throw new InvalidOperationException("Device-node limit exceeded; no incomplete discovery result was published.");}finally{SetupDiDestroyDeviceInfoList(set);}}
 }
 public static class DiscoveryWorker {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=1048576,RecursionLimit=32};
  static Dictionary<string,object> Obj(params object[] pairs){var result=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)result[(string)pairs[i]]=pairs[i+1];return result;}
  public static object Dispatch(IDictionary<string,object> request,Func<List<DiscoveryNode>> enumerate){if(request==null)throw new InvalidDataException("Request object required.");foreach(string field in request.Keys)if(field!="id"&&field!="op")throw new InvalidDataException("Unexpected request field: "+field);object op,id;if(!request.TryGetValue("op",out op)||!(op is string)||(string)op!="scan")throw new InvalidDataException("Discovery supports read-only scan only.");if(!request.TryGetValue("id",out id)||!(id is int)||(int)id<0)throw new InvalidDataException("Integer request ID required.");var devices=DiscoveryRules.Build(enumerate());return Obj("id",id,"ok",true,"data",Obj("devices",devices,"capturedAt",DateTime.Now.ToString("o"),"identificationOnly",true,"physicalCount",devices.Count(d=>d.physicalIdentityConfirmed),"unresolvedFunctionCount",devices.Count(d=>!d.physicalIdentityConfirmed),"bluetoothScope","Bluetooth vendor and live remote connection were not verified; paired records and inferred names are excluded."));}
  static int Main(string[] args){Console.InputEncoding=new UTF8Encoding(false);Console.OutputEncoding=new UTF8Encoding(false);if(args.Length==1&&args[0]=="--self-test")return SelfTest();if(args.Length!=0)return 2;string line;while((line=OpenAc.WorkerTextProtocol.ReadLine())!=null){object id=null;try{if(line.Length>65536)throw new InvalidDataException("Request too large.");var request=Json.Deserialize<Dictionary<string,object>>(line);if(request!=null)request.TryGetValue("id",out id);Console.WriteLine(Json.Serialize(Dispatch(request,WindowsDiscovery.Scan)));}catch(Exception ex){Console.WriteLine(Json.Serialize(Obj("id",id,"ok",false,"error",Obj("code","discovery_read_failed","message",ex.Message))));}}return 0;}
  static void ReviewedIdentityTests(Action<bool,string> check){
   var root=new DiscoveryNode{InstanceId=@"USB\VID_0B05&PID_1234\private-serial",Present=true,ContainerId="11111111-1111-1111-1111-111111111111",BusName="Receiver"};var orphan=new DiscoveryNode{InstanceId=@"HID\VID_0B05&PID_1234&COL01\child",ParentId=@"USB\VID_0B05&PID_1234&MI_00\missing-interface",Present=true,ContainerId=root.ContainerId};var merged=DiscoveryRules.Build(new[]{root,orphan});check(merged.Count==1&&merged[0].identityScope=="usbParent"&&merged[0].functionCount==2,"orphan HID joins unique USB root by container");
   var second=new DiscoveryNode{InstanceId=@"USB\VID_0B05&PID_5678\another-root",Present=true,ContainerId=root.ContainerId};var ambiguous=DiscoveryRules.Build(new[]{root,second,orphan});check(ambiguous.Count==3&&ambiguous.Count(d=>d.physicalIdentityConfirmed)==2&&ambiguous.Count(d=>d.identityScope=="function")==1,"shared container cannot guess orphan USB parent");
   check(DiscoveryRules.Build(new[]{new DiscoveryNode{InstanceId=@"HID\VID_046D&PID_ABCD\generic",HardwareIds=new[]{@"HID\VID_0B05&PID_ABCD"},Present=true}}).Count==0,"foreign instance VID cannot be overridden by ASUS hardware ID");
   check(DiscoveryRules.Build(new[]{new DiscoveryNode{InstanceId=@"HID\VID_0B05&PID_ABCD\generic",HardwareIds=new[]{@"HID\VID_046D&PID_ABCD"},Present=true}}).Count==0,"conflicting hardware vendor evidence excluded");
   check(DiscoveryRules.Build(new[]{new DiscoveryNode{InstanceId=@"HID\VID_0B05&PID_ABCD\generic",HardwareIds=new[]{@"HID\VID_0B05&PID_1234"},Present=true}}).Count==0,"conflicting product evidence excluded");
   root.HardwareIds=new[]{@"USB\VID_046D&PID_1234"};check(DiscoveryRules.Build(new[]{root,orphan}).Count(d=>d.identityScope=="usbParent")==0,"contradictory root cannot be used as physical parent");root.HardwareIds=new string[0];
   string json=new JavaScriptSerializer().Serialize(DiscoveryRules.Build(new[]{root,orphan}));check(!json.Contains("containerId")&&!json.Contains(root.ContainerId)&&!json.Contains("private-serial"),"discovery output omits raw container and USB instance identity");
   check(DiscoveryRules.Build(new[]{new DiscoveryNode{InstanceId=@"HID\COMPOSITE\node",HardwareIds=new[]{@"HID\VID_0B05&PID_1234"},Present=true}}).Count==1,"consistent hardware ID can identify otherwise non-VID HID node");
  }
  public static int SelfTest(){int checks=0;Action<bool,string> check=(good,name)=>{checks++;if(!good)throw new Exception(name);};string vid,pid;ReviewedIdentityTests(check);check(DiscoveryRules.ParseIdentity(@"USB\VID_0b05&PID_1aa6\serial",out vid,out pid)&&vid=="0B05"&&pid=="1AA6","strict USB VID/PID");foreach(string bad in new[]{@"PCI\VEN_0B05&DEV_0001",@"BTHENUM\DEV_0B05",@"USB\VID_0B050&PID_1234\x",@"ROOT\HID\VID_0B05&PID_1234",@"USB\VID_0B05&PID_12345\x","ROG VID_0B05&PID_1234",null})check(!DiscoveryRules.ParseIdentity(bad,out vid,out pid),"non USB identity rejected");
   var root=new DiscoveryNode{InstanceId=@"USB\VID_0B05&PID_1D54\receiver-1",Present=true,BusName="ROG OMNI RECEIVER",ContainerId="11111111-1111-1111-1111-111111111111"};var function=new DiscoveryNode{InstanceId=@"USB\VID_0B05&PID_1D54&MI_00\interface",ParentId=root.InstanceId,Present=true};var hid=new DiscoveryNode{InstanceId=@"HID\VID_0B05&PID_1DA4&MI_00&COL01\keyboard",ParentId=function.InstanceId,Present=true,FriendlyName="Paired keyboard function"};var nodes=new List<DiscoveryNode>{root,function,hid};var devices=DiscoveryRules.Build(nodes);check(devices.Count==1&&devices[0].pid=="1D54"&&devices[0].name=="ROG OMNI RECEIVER"&&devices[0].functionCount==3,"receiver functions are one physical receiver");check(devices[0].physicalIdentityConfirmed&&!devices[0].controlSupported&&devices[0].transport=="USB","identification cannot authorize control");check(devices[0].observedProductIds.SequenceEqual(new[]{"1D54","1DA4"}),"observed function PID not new physical device");check(DiscoveryRules.Build(nodes.AsEnumerable().Reverse()).Single().deviceId==devices[0].deviceId,"stable ID independent of enumeration order");nodes.Add(new DiscoveryNode{InstanceId=@"USB\VID_0B05&PID_1D54\receiver-2",Present=true,BusName="Second receiver",ContainerId=root.ContainerId});check(DiscoveryRules.Build(nodes).Count==2,"different USB parents remain separate even same container");nodes.Add(new DiscoveryNode{InstanceId=@"USB\VID_0B05&PID_FFFF\old",Present=false,BusName="Disconnected old ASUS"});nodes.Add(new DiscoveryNode{InstanceId=@"BTHENUM\DEV_fake",Present=true,FriendlyName="ROG Bluetooth paired record"});check(DiscoveryRules.Build(nodes).Count==2,"absent and unverified Bluetooth paired records excluded");
   var container=new DiscoveryNode{InstanceId=@"HID\VID_0B05&PID_1234&COL01\a",ContainerId="22222222-2222-2222-2222-222222222222",Present=true,FriendlyName="Real HID"};var other=new DiscoveryNode{InstanceId=@"HID\VID_0B05&PID_1234&COL02\b",ContainerId=container.ContainerId,Present=true};var fallback=DiscoveryRules.Build(new[]{container,other});check(fallback.Count==1&&fallback[0].identityScope=="container"&&fallback[0].transport=="unknown","HID container fallback without USB transport inference");other.InstanceId=@"HID\VID_0B05&PID_5678&COL02\b";check(DiscoveryRules.Build(new[]{container,other}).Single().pid=="","ambiguous container PID not guessed");container.InLocalMachineContainer=other.InLocalMachineContainer=true;check(DiscoveryRules.Build(new[]{container,other}).Count==2&&DiscoveryRules.Build(new[]{container,other}).All(d=>!d.physicalIdentityConfirmed),"local machine container cannot merge unrelated hardware");container.InLocalMachineContainer=other.InLocalMachineContainer=false;container.ContainerId=other.ContainerId="00000000-0000-0000-ffff-ffffffffffff";check(DiscoveryRules.Build(new[]{container,other}).Count==2&&DiscoveryRules.Build(new[]{container,other}).All(d=>!d.physicalIdentityConfirmed),"shared reserved container is not a physical-device key");container.ContainerId=null;check(!DiscoveryRules.Build(new[]{container}).Single().physicalIdentityConfirmed,"unresolved function not called physical device");foreach(var node in nodes)node.Present=false;check(DiscoveryRules.Build(nodes).Count==0,"fresh unplug scan removes all prior identities");check(DiscoveryRules.Clean("Device\n\tName")=="DeviceName"&&DiscoveryRules.Clean(new string('x',300)).Length==240,"hardware name bounded and control characters removed");int called=0;foreach(var request in new[]{Obj("id",1,"op","set"),Obj("id",1,"op","scan","path","x"),Obj("id",true,"op","scan"),Obj("id",1,"op",null)}){bool rejected=false;try{Dispatch(request,()=>{called++;return nodes;});}catch(InvalidDataException){rejected=true;}check(rejected&&called==0,"unsupported input rejected before native enumeration");}Dispatch(Obj("id",1,"op","scan"),()=>{called++;return nodes;});check(called==1,"scan is only allowed operation");Console.WriteLine("Discovery: "+checks+" pure checks passed. No native scan, device handle, command, pairing query or plugin load.");return 0;
  }
 }
}
